def _require_complete_pair(
    *,
    label: str,
    region_id: str,
    participant_set_key: str,
    left_path: Path,
    right_path: Path,
) -> None:
    left_exists = left_path.is_file()
    right_exists = right_path.is_file()
    if left_exists and right_exists:
        return
    if left_exists or right_exists:
        raise FileNotFoundError(
            "stage=%s region=%s participant_set_key=%s found partial artifact pair: %s exists=%s %s exists=%s"
            % (
                label,
                region_id,
                participant_set_key,
                left_path,
                left_exists,
                right_path,
                right_exists,
            )
        )


